  function setSelected(ticker) {
    selectedTicker = ticker;

    nodes.classed('selected', (d) => d.ticker === selectedTicker);
    tableRows.classed('selected', (d) => d.ticker === selectedTicker);

    if (selectedTicker) {
      const bubble = nodes.filter((d) => d.ticker === selectedTicker);
      bubble.raise();

      const rowNode = tableRows.filter((d) => d.ticker === selectedTicker).node();
      if (rowNode) {
        rowNode.scrollIntoView({ block: 'nearest' });
      }
    }
  }

  nodes.on('click', function (event, d) {
    event.stopPropagation();
    setSelected(d.ticker);
  });

  background.on('click', function () {
    setSelected(null);
  });

  const simulation = d3.forceSimulation(stocks)
    .force('x', d3.forceX((d) => centers.get(d.sector).x).strength(0.16))
    .force('y', d3.forceY((d) => centers.get(d.sector).y).strength(0.16))
    .force('collide', d3.forceCollide((d) => d.radius + 2).iterations(2))
    .force('charge', d3.forceManyBody().strength(-8))
    .stop();

  for (let i = 0; i < 360; i += 1) simulation.tick();

  nodes.attr('transform', (d) => `translate(${d.x.toFixed(2)},${d.y.toFixed(2)})`);

  simulation.on('tick', () => {
    nodes.attr('transform', (d) => `translate(${d.x.toFixed(2)},${d.y.toFixed(2)})`);
  });

  // ---- Table ----

  const table = d3.select('#stocks-table');
  const tbody = table.select('tbody');

  function formatMarketCap(v) {
    if (!Number.isFinite(v)) return '—';
    const abs = Math.abs(v);
    if (abs >= 1e12) return `${(v / 1e12).toFixed(2)}T`;
    if (abs >= 1e9) return `${(v / 1e9).toFixed(2)}B`;
    if (abs >= 1e6) return `${(v / 1e6).toFixed(1)}M`;
    if (abs >= 1e3) return `${(v / 1e3).toFixed(1)}K`;
    return String(v);
  }

  const tableRows = tbody.selectAll('tr')
    .data(stocks, (d) => d.ticker)
    .enter()
    .append('tr');

  tableRows.append('td').text((d) => d.ticker);
  tableRows.append('td').text((d) => d.name);
  tableRows.append('td').text((d) => d.sector);
  tableRows.append('td').text((d) => (d.marketCap === null ? '—' : formatMarketCap(d.marketCap)));

  tableRows.on('click', function (event, d) {
    event.stopPropagation();
    setSelected(d.ticker);
  });

  // Keep tooltip from getting stuck when interacting with the table.
  document.addEventListener('scroll', () => tooltip.classed('visible', false), { passive: true });
})();
"}

