{"summary": "Create CSS styling for bubble chart, table, tooltip, layout", "security_risk": "MEDIUM", "command": "create", "path": "/root/output/css/style.css", "file_text": ":root {
  --bg: #0b1220;
  --panel: #121a2b;
  --panel-2: #0f1726;
  --text: #e7eefc;
  --muted: #a8b3cc;
  --border: rgba(231, 238, 252, 0.12);
  --shadow: rgba(0, 0, 0, 0.25);
  --selected: #ffffff;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
  background: radial-gradient(1200px 800px at 20% 0%, #101a32 0%, var(--bg) 50%, #070b14 100%);
  color: var(--text);
}

header {
  padding: 18px 22px;
  border-bottom: 1px solid var(--border);
  background: linear-gradient(180deg, rgba(18, 26, 43, 0.65), rgba(18, 26, 43, 0.35));
}

header h1 {
  margin: 0;
  font-size: 18px;
  letter-spacing: 0.2px;
}

header p {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.35;
}

.layout {
  display: flex;
  gap: 14px;
  padding: 14px;
  align-items: stretch;
}

.panel {
  background: linear-gradient(180deg, rgba(18, 26, 43, 0.90), rgba(15, 23, 38, 0.85));
  border: 1px solid var(--border);
  border-radius: 14px;
  box-shadow: 0 12px 34px var(--shadow);
  overflow: hidden;
}

.panel-header {
  padding: 12px 14px;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.panel-header h2 {
  margin: 0;
  font-size: 14px;
  letter-spacing: 0.2px;
}

.panel.bubble {
  flex: 1 1 58%;
  min-width: 520px;
}

.panel.table {
  flex: 1 1 42%;
  min-width: 420px;
}

#bubble-chart {
  padding: 10px;
}

svg {
  width: 100%;
  height: auto;
  display: block;
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 10px;
  justify-content: flex-end;
  padding-top: 2px;
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 12px;
  color: var(--muted);
  white-space: nowrap;
}

.legend-swatch {
  width: 10px;
  height: 10px;
  border-radius: 3px;
  border: 1px solid rgba(255, 255, 255, 0.25);
}

.node circle {
  stroke: rgba(255, 255, 255, 0.20);
  stroke-width: 1px;
}

.node.selected circle {
  stroke: var(--selected);
  stroke-width: 3px;
}

.node text {
  font-size: 11px;
  font-weight: 700;
  fill: rgba(255, 255, 255, 0.92);
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.35);
}

.table-wrapper {
  height: calc(100vh - 130px);
  min-height: 520px;
  overflow: auto;
}

#stocks-table {
  width: 100%;
  border-collapse: collapse;
}

#stocks-table thead th {
  position: sticky;
  top: 0;
  background: rgba(18, 26, 43, 0.96);
  border-bottom: 1px solid var(--border);
  padding: 10px 10px;
  font-size: 12px;
  color: var(--muted);
  text-align: left;
  z-index: 1;
}

#stocks-table tbody td {
  border-bottom: 1px solid rgba(231, 238, 252, 0.08);
  padding: 9px 10px;
  font-size: 12.5px;
  line-height: 1.25;
}

#stocks-table tbody tr {
  cursor: pointer;
}

#stocks-table tbody tr:hover {
  background: rgba(255, 255, 255, 0.05);
}

#stocks-table tbody tr.selected {
  background: rgba(255, 255, 255, 0.10);
  outline: 1px solid rgba(255, 255, 255, 0.35);
  outline-offset: -1px;
}

.tooltip {
  position: fixed;
  max-width: 320px;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: rgba(10, 15, 28, 0.92);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
  color: var(--text);
  font-size: 12.5px;
  line-height: 1.3;
  pointer-events: none;
  opacity: 0;
  transform: translateY(6px);
  transition: opacity 0.12s ease, transform 0.12s ease;
  z-index: 50;
}

.tooltip.visible {
  opacity: 1;
  transform: translateY(0);
}

.tooltip .muted {
  color: var(--muted);
}

@media (max-width: 1100px) {
  .layout {
    flex-direction: column;
  }
  .panel.bubble, .panel.table {
    min-width: 0;
  }
  .table-wrapper {
    height: auto;
    max-height: 70vh;
  }
}
"}

