{"summary": "Create D3 visualization logic for bubble chart and linked table", "security_risk": "MEDIUM", "command": "create", "path": "/root/output/js/visualization.js", "file_text": "/* global d3 */
(function () {
  const CHART_WIDTH = 820;
  const CHART_HEIGHT = 620;

  const tooltip = d3.select('#tooltip');
  const bubbleRoot = d3.select('#bubble-chart');
  const legendRoot = d3.select('#legend');

  const csvEl = document.getElementById('stock-descriptions-csv');
  if (!csvEl) {
    bubbleRoot.append('div').text('Missing embedded CSV data.');
    return;
  }

  const rawCsv = csvEl.textContent.trim();
  const stocks = d3.csvParse(rawCsv, (d) => {
    const marketCapRaw = (d.marketCap ?? '').trim();
    const marketCap = marketCapRaw === '' ? null : Number(marketCapRaw);
    const isETF = d.sector === 'ETF' || marketCap === null || !Number.isFinite(marketCap);

    return {
      ticker: (d.ticker ?? '').trim(),
      sector: (d.sector ?? '').trim(),
      name: (d['full name'] ?? '').trim(),
      marketCap: isETF ? null : marketCap,
      isETF,
    };
  }).filter((d) => d.ticker);

  const sectors = Array.from(new Set(stocks.map((d) => d.sector))).sort(d3.ascending);

  const color = d3.scaleOrdinal()
    .domain(sectors)
    .range(d3.schemeTableau10.slice(0, Math.max(sectors.length, 1)));

  legendRoot.selectAll('.legend-item')
    .data(sectors)
    .enter()
    .append('div')
    .attr('class', 'legend-item')
    .each(function (sector) {
      const item = d3.select(this);
      item.append('span')
        .attr('class', 'legend-swatch')
        .style('background', color(sector));
      item.append('span').text(sector);
    });

  const marketCaps = stocks.filter((d) => d.marketCap !== null).map((d) => d.marketCap);
  const minCap = d3.min(marketCaps);
  const maxCap = d3.max(marketCaps);

  const rScale = d3.scaleSqrt()
    .domain([minCap ?? 1, maxCap ?? 1])
    .range([14, 56]);

  for (const d of stocks) {
    d.radius = d.marketCap === null ? 18 : rScale(d.marketCap);
  }

  const centers = (() => {
    const cx = CHART_WIDTH / 2;
    const cy = CHART_HEIGHT / 2;
    const ring = Math.min(CHART_WIDTH, CHART_HEIGHT) * 0.22;

    const map = new Map();
    sectors.forEach((s, i) => {
      const a = (Math.PI * 2 * i) / sectors.length - Math.PI / 2;
      map.set(s, { x: cx + ring * Math.cos(a), y: cy + ring * Math.sin(a) });
    });
    return map;
  })();

  const svg = bubbleRoot.append('svg')
    .attr('viewBox', `0 0 ${CHART_WIDTH} ${CHART_HEIGHT}`)
    .attr('role', 'img')
    .attr('aria-label', 'Bubble chart of stocks clustered by sector');

  const background = svg.append('rect')
    .attr('x', 0)
    .attr('y', 0)
    .attr('width', CHART_WIDTH)
    .attr('height', CHART_HEIGHT)
    .attr('fill', 'transparent');

  const nodeLayer = svg.append('g');

  const nodes = nodeLayer.selectAll('g.node')
    .data(stocks, (d) => d.ticker)
    .enter()
    .append('g')
    .attr('class', 'node')
    .style('cursor', 'pointer');

  nodes.append('circle')
    .attr('r', (d) => d.radius)
    .attr('fill', (d) => color(d.sector));

  nodes.append('text')
    .attr('text-anchor', 'middle')
    .attr('dy', '0.34em')
    .attr('pointer-events', 'none')
    .text((d) => d.ticker);

  function tooltipHtml(d) {
    return [
      `<div><strong>${escapeHtml(d.ticker)}</strong> <span class="muted">(${escapeHtml(d.sector)})</span></div>`,
      `<div class="muted">${escapeHtml(d.name)}</div>`,
    ].join('');
  }

  function escapeHtml(v) {
    return String(v)
      .replaceAll('&', '&amp;')
      .replaceAll('<', '&lt;')
      .replaceAll('>', '&gt;')
      .replaceAll('"', '&quot;')
      .replaceAll("'", '&#39;');
  }

  function moveTooltip(event) {
    const pad = 14;
    const x = Math.min(window.innerWidth - 340, event.clientX + pad);
    const y = Math.min(window.innerHeight - 120, event.clientY + pad);
    tooltip.style('left', `${x}px`).style('top', `${y}px`);
  }

  nodes
    .on('mouseover', function (event, d) {
      if (d.isETF) return;
      tooltip.classed('visible', true).html(tooltipHtml(d));
      moveTooltip(event);
    })
    .on('mousemove', function (event, d) {
      if (d.isETF) return;
      moveTooltip(event);
    })
    .on('mouseout', function () {
      tooltip.classed('visible', false);
    });

  let selectedTicker = null;

  function setSelected(ticker) {
    selectedTicker = ticker;

    nodes.classed('selected', (d) => d.ticker === selectedTicker);
    tableRows.classed('selected', (d) => d.ticker === selectedTicker);

    if (selectedTicker) {
      const bubble = nodes.filter((d) => d.ticker === selectedTicker);
      bubble.raise();

      const rowNode = tableRows.filter((d) => d.ticker === selectedTicker).node();
      if (rowNode) {
        rowNode.scrollIntoView({ block: 'nearest' });
      }
    }
  }

  nodes.on('click', function (event, d) {
    event.stopPropagation();
    setSelected(d.ticker);
  });

  background.on('click', function () {
    setSelected(null);
  });

  const simulation = d3.forceSimulation(stocks)
    .force('x', d3.forceX((d) => centers.get(d.sector).x).strength(0.16))
    .force('y', d3.forceY((d) => centers.get(d.sector).y).strength(0.16))
    .force('collide', d3.forceCollide((d) => d.radius + 2).iterations(2))
    .force('charge', d3.forceManyBody().strength(-8))
    .stop();

  for (let i = 0; i < 360; i += 1) simulation.tick();

  nodes.attr('transform', (d) => `translate(${d.x.toFixed(2)},${d.y.toFixed(2)})`);

  simulation.on('tick', () => {
    nodes.attr('transform', (d) => `translate(${d.x.toFixed(2)},${d.y.toFixed(2)})`);
  });

  // ---- Table ----

  const table = d3.select('#stocks-table');
  const tbody = table.select('tbody');

  function formatMarketCap(v) {
    if (!Number.isFinite(v)) return '—';
    const abs = Math.abs(v);
    if (abs >= 1e12) return `${(v / 1e12).toFixed(2)}T`;
    if (abs >= 1e9) return `${(v / 1e9).toFixed(2)}B`;
    if (abs >= 1e6) return `${(v / 1e6).toFixed(1)}M`;
    if (abs >= 1e3) return `${(v / 1e3).toFixed(1)}K`;
    return String(v);
  }

  const tableRows = tbody.selectAll('tr')
    .data(stocks, (d) => d.ticker)
    .enter()
    .append('tr');

  tableRows.append('td').text((d) => d.ticker);
  tableRows.append('td').text((d) => d.name);
  tableRows.append('td').text((d) => d.sector);
  tableRows.append('td').text((d) => (d.marketCap === null ? '—' : formatMarketCap(d.marketCap)));

  tableRows.on('click', function (event, d) {
    event.stopPropagation();
    setSelected(d.ticker);
  });

  // Keep tooltip from getting stuck when interacting with the table.
  document.addEventListener('scroll', () => tooltip.classed('visible', false), { passive: true });
})();
"}

